import re


def _character_class(pattern, i):
    negated = pattern.startswith("!", i)
    i += negated
    end = pattern.find("]", i + pattern.startswith("]", i))
    if end == -1:
        raise ValueError("unclosed character class")

    members = []
    while i < end:
        first = pattern[i]
        if i + 2 < end and pattern[i + 1] == "-":
            last = pattern[i + 2]
            if last < first:
                raise ValueError("descending range")
            members.extend((re.escape(first), "-", re.escape(last)))
            i += 3
        else:
            members.append(re.escape(first))
            i += 1
    return "[" + ("^" if negated else "") + "".join(members) + "]", end + 1


def _segments(pattern):
    pieces = []
    start = i = 0
    while i < len(pattern):
        char = pattern[i]
        i += 1
        if char == "\\":
            if i == len(pattern):
                raise ValueError("trailing backslash")
            char = pattern[i]
            i += 1
        elif char == "[":
            group, i = _character_class(pattern, i)
            pieces.append(group)
            continue
        elif char == "*":
            if pieces[-1:] != [".*"]:
                pieces.append(".*")
            continue
        elif char == "?":
            pieces.append(".")
            continue

        if char == "/":
            raw = pattern[start:i - 1].removesuffix("\\")
            yield None if raw == "**" else re.compile("".join(pieces), re.DOTALL)
            pieces = []
            start = i
        else:
            pieces.append(re.escape(char))
    yield None if pattern[start:] == "**" else re.compile("".join(pieces), re.DOTALL)


def matches(pattern, path):
    """Return whether the entire path matches the glob, validating every segment."""
    parts = path.split("/")
    reachable = {0}
    for segment in _segments(pattern):
        if segment is None:
            if reachable:
                reachable = set(range(min(reachable), len(parts) + 1))
        else:
            reachable = {i + 1 for i in reachable
                         if i < len(parts) and segment.fullmatch(parts[i])}
    return len(parts) in reachable
